// Gong on the company's own API key: every operation of Gong's public API (calls, transcripts, users, stats and
// scorecards, the library, trackers, CRM uploads, Engage flows and tasks, meetings, permissions, data privacy, AI
// briefs and questions about accounts and deals). actions.json is generated by `bun scripts/openapi-actions.ts gong`.
// Gong's webhooks are set up in its automation rules, not through the API, so new calls, scorecards and tasks are
// polled (polls/gong.ts).
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";

const DEFAULT_BASE = "https://api.gong.io";
const GONG_HOST = /^https:\/\/[\w.-]+\.gong\.io$/;

// The pasted key: "ACCESS_KEY:SECRET", optionally after the company's own base URL ("https://us-12345.api.gong.io ACCESS_KEY:SECRET")
export function parseKey(key: string) {
  const parts = key.trim().split(/\s+/);
  const login = parts.pop() ?? "";
  const base = (parts[0] ?? DEFAULT_BASE).replace(/\/+$/, "");
  const at = login.indexOf(":");
  return { base, access: at > 0 ? login.slice(0, at) : "", secret: at > 0 ? login.slice(at + 1) : "" };
}

export const api: Api = {
  name: "Gong",
  base: DEFAULT_BASE,
  tokenHelp: "Gong → Company settings → Ecosystem → API",
  auth: (key) => {
    const { access, secret } = parseKey(key);
    return { Authorization: `Basic ${Buffer.from(`${access}:${secret}`).toString("base64")}` };
  },
  url: (key, _base, path) => {
    const { base } = parseKey(key);
    // only Gong's own hosts, so a pasted address can't send the key elsewhere
    if (!GONG_HOST.test(base)) throw new AppsError("the base URL should look like https://us-12345.api.gong.io");
    return `${base}${path}`;
  },
};

const WORKSPACES = { method: "GET", path: "/v2/workspaces", query: [], headers: [] };

export const gong: OwnApp = {
  app: "gong",
  name: "Gong",
  logo: "/logos/gong.svg",
  keyField: {
    label: "Access key and secret",
    help: "In Gong, open Company settings → Ecosystem → API (app.gong.io/company/api); only a technical administrator sees it. Click Create, then copy the Access Key and the Access Key Secret (shown only once) and paste them joined by a colon: ACCESS_KEY:SECRET. If that page shows a base URL for your company other than https://api.gong.io, paste it first with a space: https://us-12345.api.gong.io ACCESS_KEY:SECRET",
    placeholder: "ACCESS_KEY:SECRET",
  },
  // one cheap call; a wrong key gets a 401. Labelled with the company's first workspace
  async check(key) {
    const { base, access, secret } = parseKey(key);
    if (!access || !secret) throw new AppsError("paste the Access Key and the Access Key Secret joined by a colon, like ACCESS_KEY:SECRET");
    if (!GONG_HOST.test(base)) throw new AppsError("the base URL should look like https://us-12345.api.gong.io");
    const out = (await call(api, key, WORKSPACES, {})) as { workspaces?: { name?: string }[] };
    return out.workspaces?.[0]?.name || "Gong";
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
